#!/usr/bin/env python3
"""UI3 Turbo extension: manual intent only; never changes saved stock settings."""
from pathlib import Path
p=Path('overlay/main/web/index.html');s=p.read_text()
s=s.replace('id="v2turbo" disabled title="30 Вт не проверены на физическом Gamma"','id="v2turbo" onclick="turboOpen()" title="Только ручной эксперимент"').replace('<span>TURBO · заблокирован</span>','<span>TURBO · эксперимент</span>')
s=s.replace('TURBO недоступен: допустимость 30 Вт на этом устройстве не подтверждена.','Штатные профили сохранены. TURBO открывается отдельно и требует подтверждения.')
s=s.replace('BTC HUNTER / ULTIMATE 2.0','BTC HUNTER / ULTIMATE 2.0 · UI3')
panel='''<div class="card mb" id="turboPanel"><h3>TURBO1000 <span class="tag">Ручной эксперимент</span></h3><p class="note">Это предел исследования, а не установка 1000 МГц. Управляет штатная задача тюнера: старт из проверенной точки, измерение каждой ступени и откат. Напряжение не выше 1300 мВ.</p><div class="lim"><div><label>Максимум поиска, МГц</label><input id="turboMax" type="number" min="800" max="1000" step="25" value="1000"></div><div><label>Верхний лимит БП, Вт</label><input id="turboPower" type="number" min="18" max="30" step="1" value="30"></div></div><p class="note">БП 5 В / 6 А: 30 Вт — предел, не цель. Резерв 3 Вт и погрешность учитываются автоматически. Gamma оценивает мощность косвенно: рабочий бюджет не выше 25 Вт; при просадке питания/нагреве — до 23 Вт или остановка.</p><div class="btns"><button type="button" class="btn" id="turboStart" onclick="turboStart()" disabled>Подтвердить и начать</button><button type="button" class="btn alt" id="turboStop" onclick="turboStop()" disabled>Остановить и вернуть штатный режим</button></div><p class="info" id="turboStatus">Загрузка статуса…</p><p class="note">Перед стартом нужны 30 минут проверенной стабильности в штатном режиме и принятая работа V1. Активация не сохраняется: после перезагрузки/OTA предел снова 800 МГц. Во время эксперимента настройки разгона/пулов, OTA и Benchmark заблокированы до остановки.</p><details><summary>Adaptive Silicon Map · проверенные точки</summary><div id="turboMap" class="note">Нет данных.</div></details></div>'''
s=s.replace('<section id="tuning">','<section id="tuning">'+panel)
s=s.replace("$('v2turbo').disabled=true;", "turboRender();")
s=s.replace('function v2render(s){','function v2render(s){if(!document.hidden&&(cur===\'tuning\'||cur===\'dash\'))turboLoad();')
s=s.replace("' Вт · ASIC '","' Вт · ASIC '") # existing dashboard data remains unchanged
s=s.replace("(cap>0?Math.min(25,cap):25)+' Вт", "(turboData?.armed?turboData.effectivePower:(cap>0?Math.min(25,cap):25))+' Вт")
js=r'''
let turboData=null,turboBusy=false,turboCommand=false,turboPoll=0;
const turboReasons={none:'Ожидание измерений',frequency:'Достигнут выбранный предел частоты',power:'Ограничение мощности / запаса БП',temperature:'Температура ASIC/VRM или охлаждение',supply:'Питание: VIN, ток или выходное напряжение',errors:'Аппаратные ошибки / нестабильный хешрейт или принятая работа',network:'Сеанс пула, потеря ответа или ошибка отправки',pll:'Не удалось подготовить/записать поддерживаемую PLL ступень',user:'Остановка пользователем',settings:'Изменены настройки / режим',storage:'Недостаточно NVS / ошибка записи карты',telemetry:'Недостоверная или устаревшая телеметрия',insufficient_accepted_work:'Недостаточно принятых шар для проверки',controller:'Нет heartbeat штатного тюнера',voltage:'Достигнут предел 1300 мВ',fault_hold:'Ограничение после аппаратной аварии'};
function turboRender(){const d=turboData,armed=!!d?.armed;const button=$('v2turbo');if(button)button.disabled=!d||turboCommand;$('turboStart').disabled=!d||armed||turboCommand;$('turboStop').disabled=!armed||turboCommand;$('turboMax').disabled=$('turboPower').disabled=armed||turboCommand;
 const states=['Выключен · штатный предел 800 МГц','Запрос принят штатным тюнером','Измеряем режимы','Удерживаем проверенную точку','Остановлен · штатный режим','Останавливаем / выполняем откат'];
 $('turboStatus').textContent=d?(states[d.state]||'Неизвестный статус')+' · '+(turboReasons[d.reason]||d.reason)+' · потолок '+d.maxFreq+' МГц · запрос '+d.requestedPower+' Вт / бюджет '+d.effectivePower+' Вт': 'TURBO API недоступен. Активация запрещена.';
 const map=$('turboMap');map.textContent='';for(const point of d?.points||[]){const row=document.createElement('p');row.textContent=point.frequency+' МГц / '+point.millivolts+' мВ · ASIC '+point.asicGHs+' GH/s · ACK в окне '+point.acceptedGHs+' GH/s · пик '+point.watts+' Вт · '+point.accepted+' ответов';map.append(row)}if(!map.childNodes.length)map.textContent='Пока нет проверенных TURBO точек. История не активирует эксперимент автоматически.';
 const form=document.querySelector('#tuning form');if(form)for(const e of form.querySelectorAll('button,input,select')){if(armed)e.disabled=true;else if(e.dataset.turboDisabled){e.disabled=false;delete e.dataset.turboDisabled}if(armed)e.dataset.turboDisabled='1';}
}
async function turboLoad(force=false){if(turboBusy||document.hidden||(!force&&Date.now()-turboPoll<15000))return;turboBusy=true;turboPoll=Date.now();try{const d=await readJson('/api/turbo');if(!d.available||!Array.isArray(d.points))throw Error();turboData=d}catch(e){turboData=null}finally{turboBusy=false;turboRender()}}
function turboOpen(){tab('tuning');$('turboPanel').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});turboLoad(true)}
async function turboStart(){if(!turboData||turboData.armed||turboCommand)return;const maxFreq=+$('turboMax').value,powerLimit=+$('turboPower').value;if(!Number.isInteger(maxFreq)||maxFreq<800||maxFreq>1000||maxFreq%25||!Number.isInteger(powerLimit)||powerLimit<18||powerLimit>30)return toast('Проверьте предел частоты и мощности');const confirm=prompt('Эксперимент TURBO: частота выше штатной может быть нестабильной. Тюнер исследует поддерживаемые ступени, не выставляет 1000 МГц сразу. БП требует запаса. Введите TURBO1000 для ручного подтверждения.');if(confirm!=='TURBO1000')return;await turboSend({enabled:true,confirm,maxFreq,powerLimit})}
async function turboStop(){await turboSend({enabled:false})}
async function turboSend(body){if(turboCommand)return;turboCommand=true;turboRender();try{const r=await fetch('/api/turbo',{method:'POST',body:JSON.stringify(body)});if(!r.ok){const message=await r.text();throw Error(message.includes('30min')?'Нужны 30 минут стабильного штатного режима, свежие датчики и V1 без другого эксперимента':message.includes('derated')?'Проверенная точка выше доступного бюджета БП':message)}toast(body.enabled?'Эксперимент передан штатному тюнеру':'Запрошен возврат к проверенной штатной точке');await turboLoad(true)}catch(e){toast('TURBO: '+e.message)}finally{turboCommand=false;turboRender()}}
'''
anchor='a8init();loadCfg();tick();';assert s.count(anchor)==1;s=s.replace(anchor,js+'\n'+anchor);p.write_text(s)
